<?php
require_once __DIR__ . '/config.php';
$saved_state_json = 'null';
if ($pdo) {
    try {
        $stmt = $pdo->query("SELECT state_json FROM portfolio_state WHERE id = 1");
        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        if ($row && !empty($row['state_json'])) {
            $saved_state_json = $row['state_json'];
        }
    } catch (Exception $e) {}
}
if ($saved_state_json === 'null' && file_exists(__DIR__ . '/data/portfolio_data.json')) {
    $raw = file_get_contents(__DIR__ . '/data/portfolio_data.json');
    if (!empty($raw)) $saved_state_json = $raw;
}
