    }

    .testimonials-item-card .content-card {
      width: 100%;
      height: 100%;
      padding-top: 40px;
      display: flex;
      flex-direction: column;
      justify-content: flex-start;
    }

    .testimonials-avatar-box {
      position: absolute;
      top: 0;
      left: 20px;
      transform: translateY(-24px);
      width: 58px;
      height: 58px;
      background: linear-gradient(135deg, rgba(62, 62, 70, 0.95), rgba(34, 34, 40, 0.95));
      border-radius: 16px;
      border: 1.5px solid var(--glass-border-highlight);
      box-shadow: 0 10px 24px rgba(0, 0, 0, 0.5);
      overflow: hidden;
    }

    .testimonials-avatar-box img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .testimonials-item-title {
      margin-bottom: 6px;
      padding-left: 66px;
      margin-top: -22px;
      min-height: 24px;
      display: flex;
      align-items: center;
    }

    .testimonials-text {
      color: var(--text-light-gray);
      font-size: 13px;
      font-weight: 300;
      line-height: 1.62;
      margin-top: 8px;
      display: -webkit-box;
      line-clamp: 3;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    /* Clients Marquee Item */
    .clients {
      margin-bottom: 12px;
    }

    .clients-marquee-item {
      width: 165px;
      height: 82px;
      flex-shrink: 0;
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 14px;
      padding: 12px 18px;
      display: flex;
      justify-content: center;
      align-items: center;
      transition: all 0.3s ease;
    }

    .clients-marquee-item:hover {
      background: rgba(255, 255, 255, 0.09);
      border-color: var(--glass-border-highlight);
      transform: translateY(-3px);
      box-shadow: 0 10px 24px rgba(0, 0, 0, 0.35), 0 0 16px var(--accent-glow);
    }

    .clients-marquee-item a {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .clients-marquee-item img {
      max-width: 100%;
      max-height: 52px;
      object-fit: contain;
      filter: grayscale(0.25) opacity(0.88);
      transition: 0.3s ease;
    }

    .clients-marquee-item:hover img {
      filter: grayscale(0) opacity(1) scale(1.05);
    }

    /* ============================================================
       RESUME SECTION
       ============================================================ */
    .timeline {
      margin-bottom: 32px;
    }

    .timeline .title-wrapper {
      display: flex;
      align-items: center;
      gap: 15px;
      margin-bottom: 25px;
    }

    .timeline-list {
      font-size: 13.5px;
      margin-left: 34px;
      list-style: none;
    }

    .timeline-item {
      position: relative;
      padding-bottom: 2px;
    }

    .timeline-item:not(:last-child) {
      margin-bottom: 22px;
    }

    .timeline-item-title {
      font-size: 14.5px;
      line-height: 1.35;
      margin-bottom: 5px;
      color: var(--text-white-1);
    }

    .timeline-list span {
      color: var(--accent-primary);
      font-weight: 500;
      line-height: 1.5;
      display: inline-block;
      margin-bottom: 4px;
      font-size: 12.5px;
    }

    .timeline-item:not(:last-child)::before {
      content: '';
      position: absolute;
      top: -25px;
      left: -20px;
      width: 1px;
      height: calc(100% + 50px);
      background: rgba(255, 255, 255, 0.14);
    }

    .timeline-item::after {
      content: '';
      position: absolute;
      top: 5px;
      left: -23px;
      height: 7px;
      width: 7px;
      background: linear-gradient(to right, var(--accent-primary), var(--accent-secondary));
      border-radius: 50%;
      box-shadow: 0 0 0 4px rgba(255, 255, 255, 0.08), 0 0 12px var(--accent-glow);
      transition: transform 0.25s ease, box-shadow 0.25s ease;
    }

    .timeline-item:hover::after {
      transform: scale(1.35);
      box-shadow: 0 0 0 5px var(--accent-glow), 0 0 18px var(--accent-primary);
    }

    .timeline-text {
      color: var(--text-light-gray);
      font-weight: 300;
      line-height: 1.65;
      font-size: 13.5px;
    }

    /* Skills Progress Bars */
    .skills-title {
      margin-bottom: 20px;
    }

    .skills-list {
      padding: 22px;
      list-style: none;
      cursor: default;
    }

    .skills-item:not(:last-child) {
      margin-bottom: 18px;
    }

    .skill .title-wrapper {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
      margin-bottom: 8px;
    }

    .skill .title-wrapper data {
      color: var(--accent-primary);
      font-size: 13px;
      font-weight: 600;
    }

    .skill-progress-bg {
      background: rgba(255, 255, 255, 0.09);
      width: 100%;
      height: 8px;
      border-radius: 10px;
      overflow: hidden;
    }

    .skill-progress-fill {
      background: linear-gradient(90deg, var(--accent-primary), var(--accent-secondary));
      height: 100%;
      border-radius: inherit;
      box-shadow: 0 0 14px var(--accent-glow);
      transition: width 1s cubic-bezier(0.22, 1, 0.36, 1);
    }

    /* ============================================================
       PORTFOLIO & BLOG SECTIONS (Clean Aligned Cards + External Links)
       ============================================================ */
    .filter-list {
      display: none;
      list-style: none;
    }

    .filter-select-box {
      position: relative;
      margin-bottom: 25px;
    }

    .filter-select {
      background: var(--glass-card);
      color: var(--text-light-gray);
      display: flex;
      justify-content: space-between;
      align-items: center;
      width: 100%;
      padding: 12px 16px;
      border: 1px solid var(--glass-border);
      border-radius: 14px;
      font-size: 14px;
      font-weight: 300;
      cursor: pointer;
    }

    .select-list {
      background: rgba(26, 26, 30, 0.96);
      backdrop-filter: blur(20px);
      position: absolute;
      top: calc(100% + 6px);
      width: 100%;
      padding: 6px;
      border: 1px solid var(--glass-border);
      border-radius: 14px;
      z-index: 10;
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      transition: 0.2s ease-in-out;
      list-style: none;
    }

    .filter-select.active + .select-list {
      opacity: 1;
      visibility: visible;
      pointer-events: all;
    }

    .select-item button {
      background: transparent;
      color: var(--text-light-gray);
      font-size: 14px;
      font-weight: 300;
      text-transform: capitalize;
      width: 100%;
      padding: 8px 10px;
      border-radius: 8px;
      border: none;
      text-align: left;
      cursor: pointer;
    }

    .select-item button:hover {
      background: rgba(255, 255, 255, 0.08);
      color: var(--accent-primary);
    }

    .project-list {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 12px;
      width: 100%;
      margin-bottom: 10px;
      list-style: none;
      align-items: stretch;
    }

    .project-item {
      display: none;
      width: 100%;
      min-width: 0;
      background: var(--glass-card);
      border: 1px solid var(--glass-border);
      border-radius: 14px;
      padding: 8px;
      transition: transform 0.35s ease, border-color 0.35s ease, box-shadow 0.35s ease;
    }

    .project-item.active {
      display: flex;
      flex-direction: column;
      animation: scaleUpProject 0.3s ease forwards;
    }

    .project-item:hover {
      transform: translateY(-4px);
      border-color: var(--glass-border-highlight);
      box-shadow: 0 18px 36px rgba(0, 0, 0, 0.5), 0 0 20px var(--accent-glow);
    }

    @keyframes scaleUpProject {
      0% { transform: scale(0.94); opacity: 0; }
      100% { transform: scale(1); opacity: 1; }
    }

    .project-item > a {
      width: 100%;
      height: 100%;
      min-width: 0;
      text-decoration: none;
      display: flex;
      flex-direction: column;
    }

    .project-img {
      position: relative;
      width: 100%;
      aspect-ratio: 16 / 11;
      height: auto;
      border-radius: 10px;
      overflow: hidden;
      margin-bottom: 9px;
      flex-shrink: 0;
      background: rgba(18, 18, 22, 0.8);
    }

    .project-img::before {
      content: '';
      position: absolute;
      inset: 0;
      background: transparent;
      z-index: 1;
      transition: 0.3s ease;
    }

    .project-item > a:hover .project-img::before {
      background: rgba(0, 0, 0, 0.52);
    }

    .project-item-icon-box {
      --scale: 0.8;
      background: rgba(34, 34, 40, 0.9);
      backdrop-filter: blur(10px);
      color: var(--accent-primary);
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%) scale(var(--scale));
      font-size: 20px;
      padding: 12px;
      border-radius: 12px;
      border: 1px solid var(--glass-border-highlight);
      opacity: 0;
      z-index: 2;
      transition: 0.25s ease;
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .project-item > a:hover .project-item-icon-box {
      --scale: 1;
      opacity: 1;
    }

    .project-img img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 0.45s ease;
    }

    .project-item > a:hover img {
      transform: scale(1.08);
    }

    .project-meta-row {
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      justify-content: flex-end;
      gap: 2px;
      padding: 0 4px 2px;
      margin-top: auto;
      min-width: 0;
      width: 100%;
    }

    .project-title {
      color: var(--text-white-2);
      font-size: 13.5px;
      font-weight: 500;
      text-transform: capitalize;
      line-height: 1.3;
      width: 100%;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .project-category {
      color: var(--text-Light-gray-70);
      font-size: 11.5px;
      font-weight: 300;
      width: 100%;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .link-pill-badge {
      position: absolute;
      top: 7px;
      right: 7px;
      z-index: 3;
      display: inline-flex;
      align-items: center;
      gap: 3px;
      font-size: 9.5px;
      font-weight: 600;
      color: var(--accent-primary);
      background: rgba(16, 16, 20, 0.86);
      backdrop-filter: blur(8px);
      border: 1px solid var(--glass-border-highlight);
      padding: 2.5px 7px;
      border-radius: 999px;
      white-space: nowrap;
      box-shadow: 0 4px 10px rgba(0, 0, 0, 0.45);
    }

    /* Blog Posts Grid */
    .blog-posts {
      margin-bottom: 10px;
    }

    .blog-posts-list {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 12px;
      width: 100%;
      list-style: none;
      align-items: stretch;
    }

    .blog-post-item {
      display: flex;
      width: 100%;
      min-width: 0;
    }

    .blog-post-item > a {
      position: relative;
      background: var(--glass-card);
      backdrop-filter: blur(18px);
      width: 100%;
      height: 100%;
      min-width: 0;
      box-shadow: var(--shadow-card);
      border-radius: 14px;
      border: 1px solid var(--glass-border);
      overflow: hidden;
      z-index: 1;
      display: flex;
      flex-direction: column;
      text-decoration: none;
      transition: transform 0.35s ease, border-color 0.35s ease, box-shadow 0.35s ease;
    }

    .blog-post-item > a:hover {
      transform: translateY(-4px);
      border-color: var(--glass-border-highlight);
      box-shadow: 0 18px 38px rgba(0, 0, 0, 0.5), 0 0 22px var(--accent-glow);
    }

    .blog-banner-box {
      position: relative;
      width: 100%;
      aspect-ratio: 16 / 11;
      height: auto;
      overflow: hidden;
      flex-shrink: 0;
      background: rgba(18, 18, 22, 0.8);
    }

    .blog-banner-box img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 0.45s ease;
    }

    .blog-post-item > a:hover .blog-banner-box img {
      transform: scale(1.08);
    }

    .blog-hover-badge {
      position: absolute;
      inset: 0;
      background: rgba(0, 0, 0, 0.48);
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0;
      transition: opacity 0.25s ease;
    }

    .blog-post-item > a:hover .blog-hover-badge {
      opacity: 1;
    }

    .blog-content {
      padding: 10px 11px;
      flex: 1;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 6px;
      min-width: 0;
    }

    .blog-meta {
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      align-items: flex-start;
      gap: 4px;
      height: 100%;
    }

    .blog-meta .blog-category {
      color: var(--text-white-2);
      font-size: 12px;
      font-weight: 400;
      line-height: 1.4;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .blog-meta time {
      color: var(--accent-primary);
      font-size: 11px;
      font-weight: 500;
      margin-top: auto;
    }

    .blog-Meta-dot {
      display: none;
    }

    .blog-meta time {
      color: var(--accent-primary);
      font-weight: 500;
    }

    .blog-Meta-dot {
      background: var(--accent-primary);
      width: 4px;
      height: 4px;
      border-radius: 4px;
      flex-shrink: 0;
    }

    /* ============================================================
       CONTACT SECTION
       ============================================================ */
    .mapbox {
      position: relative;
      height: 260px;
      width: 100%;
      border-radius: 16px;
      margin-bottom: 30px;
      border: 1px solid var(--glass-border);
      overflow: hidden;
      background: rgba(20, 20, 24, 0.8);
    }

    .mapbox figure {
      height: 100%;
    }

    .mapbox iframe {
      width: 100%;
      height: 100%;
      border: none;
      filter: grayscale(1) invert(1) contrast(0.92);
    }

    .contact-form {
      margin-bottom: 10px;
    }

    .form-title {
      margin-bottom: 20px;
    }

    .input-wrapper {
      display: grid;
      grid-template-columns: 1fr;
      gap: 20px;
      margin-bottom: 20px;
    }

    .form-input {
      color: var(--text-white-2);
      font-size: 13.5px;
      font-weight: 400;
      padding: 12px 16px;
      background: rgba(255, 255, 255, 0.05);
      border: 1px solid var(--glass-border);
      border-radius: 12px;
      outline: none;
      width: 100%;
      transition: border-color 0.25s ease, box-shadow 0.25s ease, background 0.25s ease;
    }

    .form-input::placeholder {
      color: var(--text-Light-gray-70);
    }

    .form-input:focus {
      border-color: var(--accent-primary);
      background: rgba(255, 255, 255, 0.08);
      box-shadow: 0 0 15px var(--accent-glow);
    }

    select.form-input,
    select {
      color-scheme: dark;
      background-color: #18181b !important;
      color: #fafafa !important;
      cursor: pointer;
    }

    select.form-input option,
    select option {
      background-color: #18181b !important;
      color: #fafafa !important;
      padding: 10px 14px;
      font-size: 13.5px;
    }

    textarea.form-input {
      min-height: 100px;
      height: 120px;
      max-height: 220px;
      resize: vertical;
      margin-bottom: 18px;
    }

    .form-btn {
      position: relative;
      width: 100%;
      background: linear-gradient(135deg, rgba(255, 219, 112, 0.22), rgba(38, 38, 45, 0.9));
      color: var(--accent-primary);
      display: inline-flex;
      justify-content: center;
      align-items: center;
      gap: 8px;
      padding: 12px 20px;
      border-radius: 12px;
      font-size: 13.5px;
      font-weight: 500;
      border: 1px solid var(--glass-border-highlight);
      box-shadow: var(--shadow-card);
      cursor: pointer;
      transition: all 0.25s ease;
    }

    .form-btn:hover:not(:disabled) {
      background: linear-gradient(135deg, var(--accent-primary), var(--accent-secondary));
      color: #111;
      transform: translateY(-2px);
      box-shadow: 0 12px 28px var(--accent-glow);
    }

    /* ============================================================
       MODALS & USER-FRIENDLY ADMIN CMS
       ============================================================ */
    .modal-container {
      position: fixed;
      inset: 0;
      display: flex;
      justify-content: center;
      align-items: center;
      overflow-y: auto;
      overscroll-behavior: contain;
      z-index: 50;
      pointer-events: none;
      visibility: hidden;
      padding: 14px;
    }

    .modal-container.active {
      pointer-events: all;
      visibility: visible;
    }

    .overlay {
      position: fixed;
      inset: 0;
      background: rgba(5, 5, 8, 0.80);
      backdrop-filter: blur(10px);
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      z-index: 1;
      transition: 0.25s ease-in-out;
    }

    .overlay.active {
      opacity: 1;
      visibility: visible;
      pointer-events: all;
    }

    .testimonials-modal {
      background: rgba(24, 24, 30, 0.96);
      backdrop-filter: blur(28px);
      position: relative;
      padding: 24px;
      margin: auto;
      border: 1px solid var(--glass-border-highlight);
      border-radius: 22px;
      box-shadow: var(--shadow-glass);
      transform: scale(1.06);
      opacity: 0;
      transition: 0.25s ease-in-out;
      z-index: 2;
      max-width: 640px;
      width: 100%;
    }

    .modal-container.active .testimonials-modal {
      transform: scale(1);
      opacity: 1;
    }

    .modal-close-btn {
      position: absolute;
      top: 15px;
      right: 15px;
      background: rgba(255, 255, 255, 0.08);
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 10px;
      width: 34px;
      height: 34px;
      display: flex;
      justify-content: center;
      align-items: center;
      color: var(--text-white-2);
      font-size: 18px;
      cursor: pointer;
      transition: 0.2s ease;
    }

    .modal-close-btn:hover {
      background: var(--accent-primary);
      color: #111;
    }

    /* Admin Tab Navigation - Fixed Height & Clean Wrap (Fixes Screenshot 57 Clipping) */
    .admin-nav-bar {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 8px;
      padding: 12px 20px;
      background: rgba(14, 14, 18, 0.95);
      border-bottom: 1px solid rgba(255, 255, 255, 0.1);
      flex-shrink: 0;
    }

    .admin-tab-btn {
      padding: 8px 14px;
      border-radius: 10px;
      font-size: 12px;
      font-weight: 500;
      line-height: 1.3;
      color: #a1a1aa;
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid rgba(255, 255, 255, 0.08);
      cursor: pointer;
      transition: all 0.2s ease;
      white-space: nowrap;
    }

    .admin-tab-btn:hover {
      color: #fff;
      background: rgba(255, 255, 255, 0.09);
    }

    .admin-tab-btn.active {
      color: #111;
      background: var(--accent-primary);
      border-color: var(--accent-primary);
      font-weight: 600;
      box-shadow: 0 4px 14px var(--accent-glow);
    }

    /* ============================================================
       RESPONSIVE BREAKPOINTS
       ============================================================ */
    @media (min-width: 580px) {
      main {
        margin-top: 50px;
        margin-bottom: 100px;
        padding: 0;
      }

      .sidebar, article {
        width: 520px;
        margin-inline: auto;
        padding: 28px;
      }

      .testimonials-item-card {
        width: 320px;
      }

      .timeline-list {
        margin-left: 45px;
        font-size: 14px;
      }

      .timeline-item:not(:last-child)::before {
        left: -30px;
      }

      .timeline-item::after {
        left: -33px;
      }

      .project-list,
      .blog-posts-list {
        gap: 18px;
      }

      .project-item {
        padding: 10px;
        border-radius: 16px;
      }

      .project-title {
        font-size: 14.5px;
      }

      .project-category {
        font-size: 12.5px;
      }

      .blog-content {
        padding: 14px 16px;
      }

      .blog-meta .blog-category {
        font-size: 13px;
      }

      .article-title {
        font-weight: 600;
        padding-bottom: 14px;
      }

      .article-title::after {
        width: 42px;
        height: 5px;
      }

      .icon-box {
        width: 44px;
        height: 44px;
        border-radius: 12px;
        font-size: 18px;
      }

      .sidebar {
        max-height: 180px;
        margin-bottom: 28px;
      }

      .sidebar.active {
        max-height: 600px;
      }

      .sidebar-info {
        gap: 22px;
      }

      .avatar-box-3d {
        width: 118px;
        height: 118px;
        border-radius: 28px;
      }

      .avatar-inner-stage,
      .avatar-glass-sheen {
        border-radius: 27px;
      }

      .info-content .name {
        font-size: 24px;
        margin-bottom: 10px;
      }

      .info-content .title {
        padding: 5px 15px;
        font-size: 12px;
      }

      .info_more-btn {
        top: -28px;
        right: -28px;
        padding: 10px 15px;
      }

      .info_more-btn span {
        display: block;
        font-size: 12px;
      }

      .separator {
        margin: 24px 0;
      }

      .project-img, .blog-banner-box {
        aspect-ratio: 16 / 10;
        height: auto;
      }

      .input-wrapper {
        grid-template-columns: 1fr 1fr;
      }

      .form-btn {
        width: max-content;
      }
    }

    @media (min-width: 768px) {
      .sidebar, article {
        width: 700px;
      }

      .contacts-list {
        grid-template-columns: 1fr 1fr;
